head.script:
scwin.openPage = function(srd){
	var tabId = "Test"+String(Math.random()).substring(2);
	var tabOptions = {
			"label": "Test"+String(Math.random()).substring(2),
			"title": "dataObject",
			"openAction": "new",
			"closable": "true"
		};
	var contentOptions = {
			"src": srd,
			"frameMode" : "pageFrame",
			"scope" : true,
			"alwaysDraw": "true"
		};
	wdc_main.addTab(tabId, tabOptions, contentOptions)
		.then(function(_tabId){
			wdc_main.setSelectedTabIndex(wdc_main.getSelectedTabIndex(_tabId));
		});
};

scwin.trigger1_onclick = function(e) {
	scwin.openPage("/sample/common_link/tabControl_popup_frModel_scrlErr_WAEA-216_(WSQ-5983)_sub.xml");
};

	scwin.setSimulate1 = function() {
		(document.getElementById('wdc_main_container') || document.getElementById('mf_wdc_main_container')).querySelectorAll('input')[1].scrollIntoView(({behavior:'smooth', block:'start'}));
	};

	scwin.setOffset = function() {
		window.offset = (document.getElementById('wdc_main_container') || document.getElementById('mf_wdc_main_container')).querySelectorAll('input')[1].getBoundingClientRect().top;
	};

	scwin.checkVal = function() {
		return window.offset == (document.getElementById('wdc_main_container') || document.getElementById('mf_wdc_main_container')).querySelectorAll('input')[1].getBoundingClientRect().top;
	};
